function norm(s){ return (s||"").toString().trim().toLowerCase(); }

function pctColor(p){
  if(p>=0.85) return "#1c9c62";
  if(p>=0.60) return "#c9a227";
  return "#c23a3a";
}

// ---------- normalização de linhas vindas do CSV (planilha real) ----------
function normPessoaRow(r){
  const get = (k)=> (r[k] ?? r[k?.toUpperCase?.()] ?? "").toString().trim();
  const lat = parseFloat(r.lat), lon = parseFloat(r.lon);
  let status = norm(get("status"));
  if(!STATUS_SET.has(status)) status = "sem_info";
  return {
    nome: get("nome"),
    funcao: get("funcao"),
    departamento: get("departamento"),
    gestor: get("gestor"),
    unidade: get("unidade"),
    cidade: get("cidade"),
    uf: get("uf"),
    lat: isNaN(lat) ? null : lat,
    lon: isNaN(lon) ? null : lon,
    data: get("data") || null,
    observacao: get("observacao"),
    status: status,
    modelo_smartphone: get("modelo_smartphone"),
    telefone: get("telefone")
  };
}
function normUnidadeRow(name, r){
  const lat = parseFloat(r.lat), lon = parseFloat(r.lon);
  return {
    cidade: (r.cidade||"").toString().trim(),
    uf: (r.uf||"").toString().trim() || null,
    lat: isNaN(lat) ? -15.8 : lat,
    lon: isNaN(lon) ? -50.5 : lon,
    confirmado: norm(r.confirmado) === "sim" || r.confirmado === true,
    marca: norm(r.marca) || (HORSCH_UNITS.has(norm(name)) ? "bouwman_horsch" : "bouwman"),
    foto_url: (r.foto_url||"").toString().trim()
  };
}

function forceHorschBrand(unidades){
  Object.keys(unidades).forEach(name=>{
    if(HORSCH_UNITS.has(norm(name))) unidades[name].marca = "bouwman_horsch";
  });
  return unidades;
}
function applyLocalUnitPhotos(unidades){
  Object.entries(LOCAL_UNIT_PHOTOS).forEach(([name, photo])=>{
    if(unidades[name]){
      unidades[name].foto_url = photo;
      unidades[name].foto_fallback = photo;
    }
  });
  return unidades;
}
function applyKnownUnitLocations(unidades, pessoas){
  Object.entries(KNOWN_UNIT_LOCATIONS).forEach(([name, location])=>{
    if(unidades[name]) Object.assign(unidades[name], location, {confirmado:true});
    pessoas.forEach(person=>{
      if(person.unidade === name) Object.assign(person, location);
    });
  });
  return {unidades, pessoas};
}

function fetchCsv(url){
  return new Promise((resolve, reject)=>{
    Papa.parse(url, {
      download:true, header:true, skipEmptyLines:true,
      complete: (res)=> resolve(res.data),
      error: (err)=> reject(err)
    });
  });
}

async function loadData(){
  if(PESSOAS_CSV_URL && UNIDADES_CSV_URL){
    try{
      const [pessoasRows, unidadesRows] = await Promise.all([
        fetchCsv(PESSOAS_CSV_URL), fetchCsv(UNIDADES_CSV_URL)
      ]);
      const pessoas = pessoasRows.filter(r=>r.nome && r.nome.trim()).map(normPessoaRow);
      const unidades = {};
      unidadesRows.forEach(r=>{
        const name = (r.unidade||"").toString().trim();
        if(name) unidades[name] = normUnidadeRow(name, r);
      });
      if(pessoas.length && Object.keys(unidades).length){
        forceHorschBrand(unidades);
        applyLocalUnitPhotos(unidades);
        applyKnownUnitLocations(unidades, pessoas);
        return {pessoas, unidades, fromSheet:true};
      }
    }catch(err){
      console.error("Falha ao carregar da planilha, usando dados incorporados.", err);
    }
  }
  const fallback = JSON.parse(JSON.stringify(EMBEDDED_DATA));
  forceHorschBrand(fallback.unidades);
  applyLocalUnitPhotos(fallback.unidades);
  applyKnownUnitLocations(fallback.unidades, fallback.pessoas);
  return {pessoas: fallback.pessoas, unidades: fallback.unidades, fromSheet:false};
}

// ---------- boot ----------
let PESSOAS = [];
let UNIDADES = {};
let unitStats = {};

async function boot(){
  const loaded = await loadData();
  const inventoryLoaded = await loadInventoryData();
  PESSOAS = loaded.pessoas;
  UNIDADES = loaded.unidades;
  INVENTARIO = applyInventoryLocalState(inventoryLoaded.rows);
  inventoryFromSheet = inventoryLoaded.fromSheet;

  buildUnitStats();
  renderKpis();
  renderUnitList();
  renderMap();
  setupTableFilters();
  applyFilters();
  renderInventoryKpis();
  setupInventoryFilters();
  setupInventoryCategories();
  setupInventoryModelMenu();
  applyInventoryFilters();
  setupTabs();
  setupDynamicControls();
}

function buildUnitStats(){
  unitStats = {};
  Object.keys(UNIDADES).forEach(u=>{
    unitStats[u] = {total:0, atualizado:0, pendente:0, sem_protecao:0, indisponivel:0, sem_info:0, gestores:{}};
  });
  PESSOAS.forEach(p=>{
    if(!unitStats[p.unidade]){
      unitStats[p.unidade] = {total:0, atualizado:0, pendente:0, sem_protecao:0, indisponivel:0, sem_info:0, gestores:{}};
      UNIDADES[p.unidade] = UNIDADES[p.unidade] || {cidade:p.cidade, uf:p.uf, lat:p.lat||-15.8, lon:p.lon||-50.5, confirmado:false, marca: HORSCH_UNITS.has(norm(p.unidade)) ? "bouwman_horsch" : "bouwman", foto_url:""};
    }
    const s = unitStats[p.unidade];
    s.total++;
    s[p.status] = (s[p.status]||0) + 1;
    const g = p.gestor || "Sem gestor definido";
    s.gestores[g] = s.gestores[g] || {total:0, atualizado:0};
    s.gestores[g].total++;
    if(p.status==="atualizado") s.gestores[g].atualizado++;
  });
}

function brandBadgesHtml(marca, size){
  if(marca === "bouwman_horsch") return `<span class="brand-badges">
    <img src="${LOGO_BOUWMAN_COLOR}" alt="Bouwman" style="height:${size}px">
    <img src="${LOGO_HORSCH_COLOR}" alt="Horsch" style="height:${size}px">
  </span>`;
  return `<span class="brand-badges partner">
    <img src="assets/Krone.png" alt="Krone">
    <img src="assets/Triolet.svg" alt="Triolet">
  </span>`;
}

// ---------- KPI cards ----------
function renderKpis(){
  const totalPessoas = PESSOAS.length;
  const totalAtualizado = PESSOAS.filter(p=>p.status==="atualizado").length;
  const totalPendente = PESSOAS.filter(p=>p.status==="pendente").length;
  const totalSemProt = PESSOAS.filter(p=>p.status==="sem_protecao").length;
  const pctGeral = totalPessoas ? totalAtualizado/totalPessoas : 0;

  document.getElementById('kpis').innerHTML = `
    <div class="kpi total"><div class="num">${totalPessoas}</div><div class="lbl">Colaboradores mapeados</div></div>
    <div class="kpi green"><div class="num">${totalAtualizado}</div><div class="lbl">Atualizados</div></div>
    <div class="kpi yellow"><div class="num">${totalPendente}</div><div class="lbl">Precisam atualizar</div></div>
    <div class="kpi red"><div class="num">${totalSemProt}</div><div class="lbl">Sem proteção</div></div>
    <div class="kpi pct"><div class="num">${(pctGeral*100).toFixed(0)}%</div><div class="lbl">Concluído no geral</div>
      <div class="bar-track"><div class="bar-fill" style="width:${(pctGeral*100).toFixed(1)}%; background:${pctColor(pctGeral)}"></div></div>
    </div>
  `;
}


// ---------- interações do mapa e seleção de unidades ----------
function locationPhotoTag(meta, name, className){
  const primary = meta.foto_url || meta.foto_fallback || '';
  if(!primary) return `<div class="${className} placeholder">📍</div>`;
  const fallback = meta.foto_fallback || '';
  return `<img class="${className}" loading="lazy" src="${primary}" data-fallback="${fallback}" alt="Foto da unidade ${name}" referrerpolicy="no-referrer" style="background:#fff" onerror="if(this.dataset.fallback && !this.dataset.fallbackUsed){this.dataset.fallbackUsed=1;this.src=this.dataset.fallback;}else{this.classList.add('photo-error');}">`;
}
function unitActionArg(name){
  return JSON.stringify(name).replace(/</g, '\\u003c');
}

function unitPeopleGroups(unitName){
  const people = PESSOAS.filter(person => person.unidade === unitName);
  const observation = person => (person.observacao || '').toString().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const semMemoria = people.filter(person => /sem armazenamento|sem memoria/.test(observation(person)));
  const semSmartphone = people.filter(person => /nao possui smartphone|nao tem smartphone|sem smartphone/.test(observation(person)));
  const atualizados = people.filter(person => person.status === 'atualizado');
  return {semMemoria, semSmartphone, atualizados};
}
function unitPeopleNames(people){
  if(!people.length) return '<span class="none">Nenhum colaborador identificado</span>';
  return people.map(person=>escHtml(person.nome || 'Sem nome')).join(' · ');
}
function unitStatusGroupsHtml(unitName){
  const groups = unitPeopleGroups(unitName);
  const line = (label, count, tone, emptyText) => `<div class="unit-summary-line ${tone}"><div class="unit-summary-head"><span>${label}</span><b>${count}</b></div><div class="unit-summary-names${count ? '' : ' none'}">${count ? 'Consulte os cards dos colaboradores abaixo' : emptyText}</div></div>`;
  return `<div class="unit-status-summary" aria-label="Resumo dos colaboradores da unidade">
    ${line('Sem memória', groups.semMemoria.length, 'danger', 'Nenhum caso identificado')}
    ${line('Não possui smartphone', groups.semSmartphone.length, 'danger', 'Nenhum caso identificado')}
    ${line('Atualizados', groups.atualizados.length, 'updated', 'Nenhum colaborador atualizado')}
  </div>`;
}

function renderSelectionSummary(name){
  const el = document.getElementById('selectionSummary');
  if(!el) return;
  if(!name || !UNIDADES[name]){
    el.className = 'selection-summary empty';
    el.innerHTML = '<span class="map-focus-chip">● Nenhuma unidade selecionada</span><span> Clique em um cartão ou marcador para abrir os detalhes da loja.</span>';
    return;
  }
  const meta = UNIDADES[name];
  const s = unitStats[name] || {total:0, atualizado:0, pendente:0, sem_protecao:0, indisponivel:0};
  const pct = s.total ? s.atualizado / s.total : 0;
  const isHorsch = meta.marca === 'bouwman_horsch';
  const partnerLabel = !isHorsch ? ' · KRONE + TRIOLIET' : '';
  el.className = 'selection-summary';
  el.innerHTML = `<span class="selection-label">Unidade em foco</span><strong>${name}${isHorsch ? ' · HORSCH' : partnerLabel}</strong><div class="selection-meta">${meta.cidade||'—'}${meta.uf ? ' · '+meta.uf : ''} · ${s.total} colaborador(es) · ${Math.round(pct*100)}% concluído</div><div class="selection-people-summary">${unitStatusGroupsHtml(name)}</div><div class="selection-actions"><button type="button" onclick="window.openPeopleForUnit(${unitActionArg(name)})">Ver colaboradores</button><button type="button" onclick="window.openInventoryForUnit(${unitActionArg(name)})">Abrir inventário</button></div>`;
}

function setActiveUnit(name){
  document.querySelectorAll('.unit-row').forEach(row=>row.classList.toggle('active', row.dataset.unit === name));
  const meta = name && UNIDADES[name] ? UNIDADES[name] : null;
  const isHorschFocus = Boolean(meta && meta.marca === 'bouwman_horsch');
  const showHorschBrand = isHorschFocus || !name;
  const isPartnerFocus = Boolean(meta && !isHorschFocus);
  document.getElementById('topbar')?.classList.toggle('horsch-focus', isHorschFocus);
  document.getElementById('topbar')?.classList.toggle('partner-focus', isPartnerFocus);
  const horschBrand = document.getElementById('horschTopbarBrand');
  if(horschBrand){ horschBrand.classList.toggle('visible', showHorschBrand); horschBrand.setAttribute('aria-hidden', String(!showHorschBrand)); }
  const partnerBrand = document.getElementById('partnerTopbarBrand');
  if(partnerBrand){ partnerBrand.classList.toggle('visible', isPartnerFocus); partnerBrand.setAttribute('aria-hidden', String(!isPartnerFocus)); }
  const brandDivider = document.getElementById('brandDivider');
  if(brandDivider){ brandDivider.classList.toggle('visible', showHorschBrand || isPartnerFocus); brandDivider.setAttribute('aria-hidden', String(!(showHorschBrand || isPartnerFocus))); }
  renderSelectionSummary(name);
  const chip = document.getElementById('mapFocusChip');
  if(chip){
    chip.className = 'map-focus-chip' + (meta && meta.marca === 'bouwman_horsch' ? ' horsch' : '');
    chip.textContent = meta ? (meta.marca === 'bouwman_horsch' ? 'Horsch em foco' : 'Unidade em foco') : 'Mapa interativo';
  }
}
function showPanelToast(message){
  let el = document.getElementById('panelToast');
  if(!el){ el = document.createElement('div'); el.id='panelToast'; el.className='toast'; document.body.appendChild(el); }
  el.textContent = message; el.classList.add('show');
  clearTimeout(window.__toastTimer); window.__toastTimer = setTimeout(()=>el.classList.remove('show'), 2200);
}
function openPeopleForUnit(name){
  const tab = document.querySelector('.tabbtn[data-tab="painel"]');
  tab?.click();
  const select = document.getElementById('fUnidade');
  if(select){ select.value = name; applyFilters(); }
  document.getElementById('employeePanel')?.scrollIntoView({behavior:'smooth', block:'start'});
  showPanelToast(`Filtrando colaboradores de ${name}`);
}
let __pendingInventoryUnit = '';
function findInventoryUnitValue(name){
  const select = document.getElementById('inventoryUnit');
  if(!select) return '';
  const target = norm(name);
  return [...select.options].find(option=>norm(option.value) === target)?.value || '';
}
function openInventoryForUnit(name){
  const tab = document.querySelector('.tabbtn[data-tab="inventario"]');
  tab?.click();
  const select = document.getElementById('inventoryUnit');
  const matchingValue = findInventoryUnitValue(name);
  if(select && matchingValue){ select.value = matchingValue; }
  else { __pendingInventoryUnit = name; }
  selectedInventoryModel = 'all';
  renderInventoryModels();
  const search = document.getElementById('inventorySearch');
  if(search) search.value = '';
  applyInventoryFilters();
  window.scrollTo({top:0, behavior:'smooth'});
  showPanelToast(`Inventário filtrado para ${name}`);
}
window.openPeopleForUnit = openPeopleForUnit;
window.openInventoryForUnit = openInventoryForUnit;

// ---------- unit list ----------
function renderUnitList(){
  const unitListEl = document.getElementById('unitList');
  unitListEl.innerHTML = '';
  Object.entries(UNIDADES).forEach(([name, meta])=>{
    const s = unitStats[name] || {total:0, atualizado:0, pendente:0, sem_protecao:0, indisponivel:0, sem_info:0};
    const pct = s.total ? s.atualizado/s.total : 0;
    const isHorsch = meta.marca === 'bouwman_horsch';
    const row = document.createElement('div');
    row.className = 'unit-row' + (isHorsch ? ' horsch' : '');
    row.dataset.unit = name;
    const thumb = locationPhotoTag(meta, name, 'unit-thumb');
    row.innerHTML = `
      ${thumb}
      <div class="unit-row-body">
        <div class="unit-row-top">
          <span class="name">${name}${meta.confirmado ? '' : ' ⚠'}${brandBadgesHtml(meta.marca, 13)}${isHorsch ? '<span class="horsch-tag">Horsch</span>' : ''}</span>
          <span class="pct" style="color:${isHorsch ? 'var(--horsch-red)' : pctColor(pct)}">${(pct*100).toFixed(0)}%</span>
        </div>
        <div class="meta">${meta.cidade||'—'}${meta.uf ? ' · '+meta.uf : ''} · ${s.total} colaborador(es)</div>
        <div class="track"><div class="fill" style="width:${(pct*100).toFixed(1)}%; background:${isHorsch ? 'var(--horsch-red)' : pctColor(pct)}"></div></div>
        <div class="micro-status"><span><b>${s.atualizado||0}</b> ok</span><span><b>${s.pendente||0}</b> pendentes</span><span><b>${s.sem_protecao||0}</b> sem proteção</span></div>
        ${unitStatusGroupsHtml(name)}
      </div>`;
    row.addEventListener('click', ()=>focusUnit(name, true));
    unitListEl.appendChild(row);
  });
}

function focusUnit(name, openPopup=true){
  const meta = UNIDADES[name];
  if(!meta) return;
  setActiveUnit(name);
  if(window.__map && window.__markers && window.__markers[name]){
    window.__map.flyTo([meta.lat, meta.lon], 7, {duration:0.6});
    if(openPopup) window.__markers[name].openPopup();
  }
  const fUnidade = document.getElementById('fUnidade');
  if(fUnidade){ fUnidade.value = name; applyFilters(); }
}

// ---------- map ----------
function renderMap(){
  try{
    if(typeof L === 'undefined') throw new Error('Leaflet não carregou (sem internet ou CDN bloqueado pela rede da empresa).');
    document.getElementById('map').innerHTML = '';
    const map = L.map('map', {scrollWheelZoom:false, zoomControl:true}).setView([-15.8, -50.5], 4);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {attribution:'&copy; OpenStreetMap contributors', maxZoom:12}).addTo(map);
    map.on('click', ()=>setActiveUnit(''));
    const markers = {};
    Object.entries(UNIDADES).forEach(([name, meta])=>{
      const s = unitStats[name] || {total:0, atualizado:0, pendente:0, sem_protecao:0, indisponivel:0, gestores:{}};
      const pct = s.total ? s.atualizado/s.total : 0;
      const radius = 8 + Math.sqrt(s.total)*3.4;
      const isHorsch = meta.marca === 'bouwman_horsch';
      const marker = L.circleMarker([meta.lat, meta.lon], {
        radius,
        color: isHorsch ? '#E30613' : (meta.confirmado ? pctColor(pct) : '#9aa2b1'),
        weight: isHorsch ? 4 : 2,
        dashArray: meta.confirmado ? null : '4,3',
        fillColor: isHorsch ? '#E30613' : pctColor(pct),
        fillOpacity: isHorsch ? .70 : .55
      }).addTo(map);
      marker.bindTooltip(`${name} · ${(pct*100).toFixed(0)}%`, {direction:'top', offset:[0,-radius], opacity:.92});
      marker.on('click', ()=>setActiveUnit(name));
      const gestorRows = Object.entries(s.gestores||{}).sort((a,b)=>b[1].total-a[1].total).map(([g,v])=>{ const gp=v.total?v.atualizado/v.total:0; return `<div class="popup-row"><span>${g}</span><span>${v.atualizado}/${v.total} (${(gp*100).toFixed(0)}%)</span></div>`; }).join('');
      const photo = locationPhotoTag(meta, name, 'popup-photo');
      const photoBlock = photo.includes('<img') ? `<div class="popup-photo-wrap">${photo}<span class="popup-photo-badge">Foto da unidade</span></div>` : photo;
      const brand = isHorsch
        ? `<div class="popup-brand"><img src="assets/bouwman-color.png" alt="Bouwman"><img src="assets/horsch-red.svg" alt="Horsch"><span class="horsch-tag">Horsch</span></div>`
        : `<div class="popup-brand partner"><img src="assets/Krone.png" alt="Krone"><img src="assets/Triolet.png" alt="Triolet"><span class="partner-tag">Krone + Triolet</span></div>`;
      const arg = unitActionArg(name);
      marker.bindPopup(`<div class="popup-card ${isHorsch ? 'horsch-card' : ''}">
        ${photoBlock}
        <div class="popup-kicker">Painel da filial</div>
        <div class="popup-title">${name}</div>
        ${brand}
        <div class="popup-location">${meta.cidade||'—'}${meta.uf ? ' · '+meta.uf : ''}${meta.confirmado ? '' : ' · localização não confirmada'}</div>
        <div class="popup-row"><b>Conclusão</b><b style="color:${isHorsch ? 'var(--horsch-red)' : pctColor(pct)}">${(pct*100).toFixed(0)}%</b></div>
        <div class="popup-progress"><div style="width:${(pct*100).toFixed(1)}%;background:${isHorsch ? 'var(--horsch-red)' : pctColor(pct)}"></div></div>
        <div class="popup-stat-grid"><div class="popup-stat"><b>${s.total||0}</b><span>colaboradores</span></div><div class="popup-stat"><b>${s.atualizado||0}</b><span>atualizados</span></div><div class="popup-stat"><b>${s.pendente||0}</b><span>pendentes</span></div><div class="popup-stat"><b>${s.sem_protecao||0}</b><span>sem proteção</span></div></div>
        <div class="popup-gestores"><div style="font-weight:700;margin-bottom:4px;">Por gestor</div>${gestorRows || '<span style="color:#7b8492">Sem gestores registrados</span>'}</div>
        <div class="popup-actions"><button type="button" onclick="window.openPeopleForUnit(${arg})">Colaboradores</button><button type="button" class="primary" onclick="window.openInventoryForUnit(${arg})">Inventário</button></div>
      </div>`);
      marker.on('popupopen', ()=>setActiveUnit(name));
      markers[name] = marker;
    });
    window.__map = map;
    window.__markers = markers;
  }catch(err){
    console.error(err);
    document.getElementById('map').innerHTML = '<div style="height:100%;display:flex;align-items:center;justify-content:center;text-align:center;padding:30px;color:#5b6478;font-size:12.5px;line-height:1.6;">⚠ O mapa não carregou (precisa de internet / o servidor de mapas pode estar bloqueado pela rede).<br>Os cartões, a lista de unidades e a tabela abaixo continuam funcionando normalmente.</div>';
  }
}

// ---------- table + filters ----------
function setupTableFilters(){
  const fUnidade = document.getElementById('fUnidade');
  const fGestor = document.getElementById('fGestor');
  fUnidade.innerHTML = '<option value="">Todas as unidades</option>';
  fGestor.innerHTML = '<option value="">Todos os gestores</option>';
  [...new Set(PESSOAS.map(p=>p.unidade))].sort().forEach(u=>{
    const o = document.createElement('option'); o.value=u; o.textContent=u; fUnidade.appendChild(o);
  });
  [...new Set(PESSOAS.map(p=>p.gestor).filter(Boolean))].sort().forEach(g=>{
    const o = document.createElement('option'); o.value=g; o.textContent=g; fGestor.appendChild(o);
  });
  const search = document.getElementById('search');
  const fStatus = document.getElementById('fStatus');
  [search, fUnidade, fGestor, fStatus].forEach(el=>el.addEventListener('input', applyFilters));
}


function personStatusDetail(person){
  const observation = (person.observacao || '').toString().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  if(/sem armazenamento|sem memoria/.test(observation)) return {label:'Sem memória no aparelho', tone:'alert'};
  if(/nao possui smartphone|nao tem smartphone|sem smartphone/.test(observation)) return {label:'Não possui smartphone', tone:'alert'};
  if(person.status === 'atualizado') return {label:'Atualizado', tone:'good'};
  if(person.status === 'sem_protecao') return {label:'Sem proteção', tone:'alert'};
  if(person.status === 'pendente') return {label:'Precisa atualizar', tone:'alert'};
  if(person.status === 'indisponivel') return {label:'Indisponível', tone:'alert'};
  return {label:'Sem informação', tone:''};
}

function renderTable(rows){
  const host = document.getElementById('peopleCards');
  if(!host) return;
  host.innerHTML = rows.length ? rows.map(p=>{
    const statusKey = p.status || 'sem_info';
    const statusLabel = STATUS_LABEL[statusKey] || 'Sem informação';
    const detail = personStatusDetail(p);
    const inventoryMatch = (typeof INVENTARIO !== 'undefined' ? INVENTARIO.find(item=>norm(item.nome) === norm(p.nome)) : null);
    const model = ((p.modelo_smartphone || '').trim() || (inventoryMatch?.modelo || '').trim());
    const phone = ((p.telefone || '').trim() || (inventoryMatch?.numero || '').trim());
    const initials = (p.nome || '?').split(/\s+/).filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase();
    const unitMeta = UNIDADES[p.unidade] || {};
    const isHorsch = unitMeta.marca === 'bouwman_horsch';
    const unitArg = unitActionArg(p.unidade || '');
    const alertClass = ['pendente','sem_protecao','indisponivel'].includes(statusKey) || detail.tone === 'alert' ? 'alert-card' : '';
    return `<article class="person-card ${alertClass}${isHorsch?' horsch-person':''}${model?'':' missing-model'}" tabindex="0" data-unit="${escHtml(p.unidade||'')}">
      <div class="person-card-head">
        <div class="person-identity"><span class="person-avatar">${initials}</span><div><strong title="${escHtml(p.nome||'')}">${escHtml(p.nome||'Sem nome')}</strong><small title="${escHtml(p.funcao||'')}">${escHtml(p.funcao||'Função não informada')}</small></div></div>
        <span class="person-status ${statusKey}">${escHtml(statusLabel)}</span>
      </div>
      <div class="person-card-reason ${detail.tone}">${escHtml(detail.label)}</div>
      <div class="person-info-grid">
        <div class="person-info-item"><span>Unidade</span><b title="${escHtml(p.unidade||'')}">${escHtml(p.unidade||'Não informada')}</b></div>
        <div class="person-info-item"><span>Gestor</span><b title="${escHtml(p.gestor||'')}">${escHtml(p.gestor||'Não informado')}</b></div>
        <div class="person-info-item"><span>Telefone</span><b title="${escHtml(phone)}">${escHtml(phone||'Não informado')}</b></div>
        <div class="person-info-item"><span>Atualização</span><b>${escHtml(p.data||'Não informada')}</b></div>
      </div>
      <div class="person-device"><span>Modelo do aparelho</span><strong>${escHtml(model||'Modelo não informado')}</strong><small>${model?'Passe o mouse ou use Tab para visualizar o detalhe.':'Preencha o modelo para completar o cadastro.'}</small></div>
      <div class="person-card-bottom"><small>${isHorsch?'Unidade Horsch · ':''}${escHtml(p.cidade||'Cidade não informada')}${p.uf?' · '+escHtml(p.uf):''}</small><button type="button" onclick="event.stopPropagation();window.openPeopleForUnit(${unitArg})">Focar unidade</button></div>
    </article>`;
  }).join('') : '<div class="people-empty">Nenhum colaborador corresponde aos filtros selecionados.</div>';
  document.getElementById('tableCount').textContent = rows.length + ' de ' + PESSOAS.length + ' colaboradores';
  host.querySelectorAll('.person-card').forEach(card=>{
    const focus = ()=>{ if(card.dataset.unit && UNIDADES[card.dataset.unit]) focusUnit(card.dataset.unit,true); };
    card.addEventListener('click', focus);
    card.addEventListener('keydown', event=>{ if(event.key==='Enter' || event.key===' '){ event.preventDefault(); focus(); } });
  });
}

function applyFilters(){
  const q = document.getElementById('search').value.trim().toLowerCase();
  const u = document.getElementById('fUnidade').value;
  const g = document.getElementById('fGestor').value;
  const st = document.getElementById('fStatus').value;
  const rows = PESSOAS.filter(p=>{
    if(u && p.unidade!==u) return false;
    if(g && p.gestor!==g) return false;
    if(st && p.status!==st) return false;
    if(q){
      const hay = `${p.nome} ${p.funcao} ${p.cidade} ${p.gestor} ${p.unidade} ${p.modelo_smartphone} ${p.telefone}`.toLowerCase();
      if(!hay.includes(q)) return false;
    }
    return true;
  });
  renderTable(rows);
}


const INVENTORY_CATEGORY_LABELS = {
  all:'Todos', notebooks:'Notebooks', monitores:'Monitores', celulares:'Celulares',
  linha_movel:'Linha móvel', impressoras:'Impressoras', tablets:'Tablets', servidores:'Servidores', outros:'Outros'
};
let selectedInventoryCategory = 'all';
function inferInventoryCategory(row){
  const explicit = `${row.categoria||''} ${row.tipo_equipamento||''}`.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const text = `${explicit} ${row.modelo||''} ${row.numero||''} ${row.email||''}`.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if(/notebook|laptop|macbook/.test(text)) return 'notebooks';
  if(/monitor|display|tela/.test(text)) return 'monitores';
  if(/impressora|printer|multifuncional/.test(text)) return 'impressoras';
  if(/tablet|ipad|galaxy tab/.test(text)) return 'tablets';
  if(/servidor|server/.test(text)) return 'servidores';
  if(/linha movel|chip|sim card|plano movel/.test(text) || (row.numero && !row.modelo)) return 'linha_movel';
  if(/celular|smartphone|iphone|moto |motorola|galaxy|redmi|poco|xiaomi|telefone/.test(text) || row.modelo || row.numero) return 'celulares';
  return 'outros';
}
function renderInventoryCategories(){
  const host = document.getElementById('inventoryCategories');
  if(!host) return;
  const keys = ['all','notebooks','monitores','celulares','linha_movel','impressoras','tablets','servidores'];
  const counts = Object.fromEntries(keys.map(key=>[key, key === 'all' ? INVENTARIO.length : INVENTARIO.filter(row=>inferInventoryCategory(row)===key).length]));
  host.innerHTML = keys.map(key=>`<button type="button" class="inventory-category-btn${selectedInventoryCategory===key?' active':''}" data-category="${key}" aria-pressed="${selectedInventoryCategory===key}">${INVENTORY_CATEGORY_LABELS[key]} <small>${counts[key]}</small></button>`).join('');
}
function setupInventoryCategories(){
  const host = document.getElementById('inventoryCategories');
  if(!host) return;
  renderInventoryCategories();
  host.addEventListener('click', event=>{
    const button = event.target.closest('.inventory-category-btn');
    if(!button) return;
    selectedInventoryCategory = button.dataset.category || 'all';
    renderInventoryCategories();
    applyInventoryFilters();
  });
}


let selectedInventoryModel = 'all';
function modelKey(value){
  const raw = (value||'').toString().replace(/\s+/g,' ').trim();
  if(!raw) return '';
  const base = raw.split(/\s*\(\s*(?:Model|IMEI|ID|IC|MSN|P\/N|Serial|S\/N)\s*:/i)[0].trim();
  return (base || raw).toUpperCase();
}
function renderInventoryModels(){
  const host = document.getElementById('inventoryModels');
  const count = document.getElementById('inventoryModelCount');
  if(!host) return;
  const models = new Map();
  INVENTARIO.forEach(row=>{
    const model = modelKey(row.modelo) || 'Sem modelo informado';
    models.set(model, (models.get(model)||0)+1);
  });
  const ordered = [...models.entries()].sort((a,b)=>{
    if(a[0] === 'Sem modelo informado') return 1;
    if(b[0] === 'Sem modelo informado') return -1;
    return a[0].localeCompare(b[0],'pt-BR');
  });
  host.innerHTML = `<button type="button" class="inventory-model-btn${selectedInventoryModel==='all'?' active':''}" data-model="all"><span>Todos os modelos</span><small>${INVENTARIO.length}</small></button>` + ordered.map(([model,total])=>`<button type="button" class="inventory-model-btn${selectedInventoryModel===model?' active':''}" data-model="${escHtml(model)}"><span title="${escHtml(model)}">${escHtml(model)}</span><small>${total}</small></button>`).join('');
  if(count) count.textContent = ordered.length + ' modelo(s)';
}
function setupInventoryModelMenu(){
  const menu = document.getElementById('inventoryModelMenu');
  const toggle = document.getElementById('inventoryModelToggle');
  const host = document.getElementById('inventoryModels');
  if(!menu || !toggle || !host) return;
  renderInventoryModels();
  toggle.addEventListener('click', ()=>{
    const expanded = menu.classList.toggle('expanded');
    toggle.setAttribute('aria-expanded', String(expanded));
  });
  host.addEventListener('click', event=>{
    const button = event.target.closest('.inventory-model-btn');
    if(!button) return;
    selectedInventoryModel = button.dataset.model === 'all' ? 'all' : (button.dataset.model || 'all');
    renderInventoryModels();
    applyInventoryFilters();
  });
}

// ---------- aba Inventário (dados da Pasta2.xlsx) ----------
let INVENTARIO = [];
let inventoryFromSheet = false;

function normalizeHeader(value){
  return (value ?? '').toString().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase().trim();
}
function inventoryGet(row, names){
  const entries = Object.entries(row || {});
  const wanted = names.map(normalizeHeader);
  const found = entries.find(([key])=>wanted.includes(normalizeHeader(key)));
  return found && found[1] != null ? found[1].toString().trim() : '';
}
function normalizeInventoryRow(row){
  const unidadeOriginal = inventoryGet(row, ['UNIDADE','unidade']);
  const unitAliases = {
    'lem':'LEM - Bahia', 'lem e pauls':'LEM - Bahia', 'lem - bahia':'LEM - Bahia',
    'starkland':'Starkland - Castro PR', 'starkland - castro pr':'Starkland - Castro PR',
    'corporativo':'Corporativo - Castro PR', 'corporativo - castro pr':'Corporativo - Castro PR'
  };
  const unidade = unitAliases[unidadeOriginal.toLowerCase()] || unidadeOriginal;
  return {
    nome: inventoryGet(row, ['NOME','nome']),
    numero: inventoryGet(row, ['NÚMERO','NUMERO','numero']),
    email: inventoryGet(row, ['E-MAIL','EMAIL','email']),
    modelo: inventoryGet(row, ['MODELO','modelo']),
    nf_equipamento: inventoryGet(row, ['NF EQUIPAMENTO','nf_equipamento']),
    data_aquisicao: inventoryGet(row, ['DATA AQUISIÇÃO','DATA DE AQUISIÇÃO','data_aquisicao']),
    data_entrega: inventoryGet(row, ['DATA DE ENTREGA','data_entrega']),
    valor_aquisicao: inventoryGet(row, ['VALOR AQUISIÇÃO','VALOR DE AQUISIÇÃO','valor_aquisicao']),
    empresa: inventoryGet(row, ['EMPRESA','empresa']),
    unidade: unidade,
    unidade_original: unidadeOriginal,
    categoria: inventoryGet(row, ['CATEGORIA','categoria','TIPO','TIPO DE EQUIPAMENTO','tipo_equipamento','EQUIPAMENTO']),
    departamento: inventoryGet(row, ['DEPARTAMENTO','departamento']),
    gestor: inventoryGet(row, ['GESTOR','gestor']),
    funcao: inventoryGet(row, ['FUNÇÃO','FUNCAO','funcao']),
    email_corporativo: inventoryGet(row, ['ENDEREÇO E-MAIL','ENDERECO E-MAIL','EMAIL CORPORATIVO','email_corporativo']),
    observacoes: inventoryGet(row, ['OBSERVAÇÕES','OBSERVACOES','observacoes'])
  };
}

// ---------- editor local do Inventário (sem senhas ou códigos de desbloqueio) ----------
const INVENTORY_LOCAL_STORAGE_KEY = 'bouwman_inventario_edicoes_v1';
const INVENTORY_EDITABLE_FIELDS = ['nome','numero','email','modelo','categoria','nf_equipamento','data_aquisicao','data_entrega','valor_aquisicao','empresa','unidade','departamento','gestor','funcao','email_corporativo','observacoes'];
function inventoryKeyPart(value){
  return normalizeHeader(value).replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,64) || 'sem-dado';
}
function inventoryBaseId(row){
  return 'base-' + inventoryKeyPart(row.nome) + '-' + inventoryKeyPart(row.unidade);
}
function inventoryLocalId(){
  return 'local-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2,8);
}
function cleanInventoryRecord(source){
  const record = {};
  INVENTORY_EDITABLE_FIELDS.forEach(field=>{ record[field] = (source?.[field] ?? '').toString().trim(); });
  return record;
}
function defaultInventoryLocalState(){ return {version:1, updates:{}, added:[]}; }
function readInventoryLocalState(){
  try{
    const raw = window.localStorage.getItem(INVENTORY_LOCAL_STORAGE_KEY);
    if(!raw) return defaultInventoryLocalState();
    const parsed = JSON.parse(raw);
    return {
      version:1,
      updates: parsed && parsed.updates && typeof parsed.updates === 'object' ? parsed.updates : {},
      added: Array.isArray(parsed?.added) ? parsed.added : []
    };
  }catch(error){
    console.warn('Não foi possível ler as edições locais do Inventário.', error);
    return defaultInventoryLocalState();
  }
}
function writeInventoryLocalState(state){
  try{ window.localStorage.setItem(INVENTORY_LOCAL_STORAGE_KEY, JSON.stringify(state)); return true; }
  catch(error){ console.warn('Não foi possível salvar as edições locais do Inventário.', error); return false; }
}
function applyInventoryLocalState(rows){
  const state = readInventoryLocalState();
  const baseRows = (rows || []).map(row=>({...row, __id:row.__id || inventoryBaseId(row)}));
  const merged = baseRows.map(row=>({...row, ...(state.updates[row.__id] || {}), __id:row.__id}));
  const added = state.added.map(row=>({...cleanInventoryRecord(row), ...row, __id:row.__id || inventoryLocalId()}));
  return merged.concat(added);
}
function refreshInventoryUnitOptions(){
  const select = document.getElementById('inventoryUnit');
  const datalist = document.getElementById('inventoryUnitDatalist');
  const previous = select?.value || '';
  const units = [...new Set(INVENTARIO.map(r=>r.unidade).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
  if(select){
    select.innerHTML = '<option value="">Todas as unidades</option>';
    units.forEach(name=>{ const option=document.createElement('option'); option.value=name; option.textContent=name; select.appendChild(option); });
    if(units.includes(previous)) select.value = previous;
  }
  if(datalist){ datalist.innerHTML = units.map(name=>`<option value="${escHtml(name)}"></option>`).join(''); }
}
function openInventoryEditor(row, mode='edit'){
  const modal = document.getElementById('inventoryModal');
  const form = document.getElementById('inventoryForm');
  if(!modal || !form) return;
  const isEdit = mode === 'edit' && row;
  const source = isEdit ? row : {};
  const valueMap = {
    invNome:'nome', invNumero:'numero', invEmail:'email', invModelo:'modelo', invCategoria:'categoria',
    invNf:'nf_equipamento', invDataAquisicao:'data_aquisicao', invDataEntrega:'data_entrega', invValor:'valor_aquisicao',
    invEmpresa:'empresa', invUnidade:'unidade', invDepartamento:'departamento', invGestor:'gestor', invFuncao:'funcao',
    invEmailCorporativo:'email_corporativo', invObservacoes:'observacoes'
  };
  Object.entries(valueMap).forEach(([elementId, field])=>{
    const element = document.getElementById(elementId); if(!element) return;
    element.value = isEdit ? (source[field] || '') : (field === 'empresa' ? 'Bouwman' : field === 'categoria' ? 'Smartphone' : field === 'unidade' ? (document.getElementById('inventoryUnit')?.value || '') : '');
  });
  document.getElementById('inventoryEditId').value = isEdit ? (row.__id || '') : '';
  document.getElementById('inventoryFormMode').value = isEdit ? 'edit' : 'add';
  document.getElementById('inventoryModalTitle').textContent = isEdit ? 'Editar equipamento' : 'Adicionar equipamento';
  document.getElementById('inventoryModalNote').textContent = isEdit ? 'Altere os dados necessários. Ao salvar, o cartão, os filtros e os indicadores serão atualizados neste navegador.' : 'Os campos abaixo são o padrão do cadastro. Preencha somente as informações disponíveis; o registro ficará salvo neste navegador.';
  modal.classList.add('open');
  modal.setAttribute('aria-hidden','false');
  setTimeout(()=>document.getElementById('invNome')?.focus(), 30);
}
function closeInventoryEditor(){
  const modal = document.getElementById('inventoryModal');
  if(!modal) return;
  modal.classList.remove('open');
  modal.setAttribute('aria-hidden','true');
}
function refreshInventoryViews(){
  renderInventoryKpis();
  renderInventoryCategories();
  renderInventoryModels();
  refreshInventoryUnitOptions();
  applyInventoryFilters();
}
function saveInventoryFromForm(){
  const form = document.getElementById('inventoryForm');
  if(!form) return;
  const valueMap = {
    invNome:'nome', invNumero:'numero', invEmail:'email', invModelo:'modelo', invCategoria:'categoria',
    invNf:'nf_equipamento', invDataAquisicao:'data_aquisicao', invDataEntrega:'data_entrega', invValor:'valor_aquisicao',
    invEmpresa:'empresa', invUnidade:'unidade', invDepartamento:'departamento', invGestor:'gestor', invFuncao:'funcao',
    invEmailCorporativo:'email_corporativo', invObservacoes:'observacoes'
  };
  const source = {};
  Object.entries(valueMap).forEach(([elementId, field])=>{ source[field] = document.getElementById(elementId)?.value || ''; });
  const record = cleanInventoryRecord(source);
  if(!record.nome){ showPanelToast('Informe o nome ou responsável pelo equipamento.'); document.getElementById('invNome')?.focus(); return; }
  const state = readInventoryLocalState();
  const mode = document.getElementById('inventoryFormMode').value;
  const id = document.getElementById('inventoryEditId').value;
  if(mode === 'edit' && id){
    state.updates[id] = record;
    const index = INVENTARIO.findIndex(row=>row.__id === id);
    if(index >= 0) INVENTARIO[index] = {...INVENTARIO[index], ...record, __id:id};
  }else{
    const newRow = {...record, unidade_original:record.unidade, __id:inventoryLocalId()};
    state.added.push(newRow);
    INVENTARIO.push(newRow);
  }
  if(!writeInventoryLocalState(state)){ showPanelToast('Não foi possível salvar no navegador.'); return; }
  closeInventoryEditor();
  refreshInventoryViews();
  showPanelToast(mode === 'edit' ? 'Equipamento atualizado.' : 'Equipamento adicionado.');
}
function setupInventoryEditor(){
  document.getElementById('btnInventoryAdd')?.addEventListener('click', ()=>openInventoryEditor(null,'add'));
  document.querySelectorAll('[data-inventory-close]').forEach(element=>element.addEventListener('click', closeInventoryEditor));
  document.getElementById('inventoryForm')?.addEventListener('submit', event=>{ event.preventDefault(); saveInventoryFromForm(); });
  document.getElementById('inventoryBody')?.addEventListener('click', event=>{
    const button = event.target.closest('[data-inventory-edit]');
    if(!button) return;
    const row = INVENTARIO.find(item=>item.__id === button.dataset.inventoryEdit);
    if(row) openInventoryEditor(row,'edit');
  });
  document.addEventListener('keydown', event=>{ if(event.key === 'Escape') closeInventoryEditor(); });
}

async function loadInventoryData(){
  if(INVENTARIO_CSV_URL){
    try{
      const rows = await fetchCsv(INVENTARIO_CSV_URL);
      const normalized = rows.filter(r=>inventoryGet(r,['NOME','nome'])).map(normalizeInventoryRow);
      if(normalized.length){ return {rows:normalized, fromSheet:true}; }
    }catch(err){ console.error('Falha ao carregar inventário da planilha.', err); }
  }
  return {rows: JSON.parse(JSON.stringify(INVENTORY_EMBEDDED_DATA)), fromSheet:false};
}
function escHtml(value){
  return (value ?? '').toString().replace(/[&<>"']/g, ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[ch]));
}
function inventoryStatus(row){
  const hasModel = Boolean((row.modelo||'').trim());
  const hasPhone = Boolean((row.numero||'').trim());
  if(hasModel && hasPhone) return {key:'complete', label:'Completo'};
  if(hasModel || hasPhone) return {key:'partial', label:'Parcial'};
  return {key:'empty', label:'Sem dados'};
}
function inventoryCell(value, className=''){
  const missing = value == null || value === '';
  const text = missing ? '<span class="missing-value">Não informado</span>' : escHtml(value);
  return `<td class="${className}${missing ? ' missing-cell' : ''}">${text}</td>`;
}
function renderInventoryKpis(){
  const total = INVENTARIO.length;
  const complete = INVENTARIO.filter(r=>inventoryStatus(r).key === 'complete').length;
  const partial = INVENTARIO.filter(r=>inventoryStatus(r).key === 'partial').length;
  const empty = INVENTARIO.filter(r=>inventoryStatus(r).key === 'empty').length;
  const units = new Set(INVENTARIO.map(r=>r.unidade).filter(Boolean)).size;
  document.getElementById('inventoryKpis').innerHTML = `
    <div class="inventory-kpi"><div class="num">${total}</div><div class="lbl">Registros na planilha</div></div>
    <div class="inventory-kpi good"><div class="num">${complete}</div><div class="lbl">Cadastro completo</div></div>
    <div class="inventory-kpi warn"><div class="num">${partial}</div><div class="lbl">Cadastro parcial</div></div>
    <div class="inventory-kpi alert"><div class="num">${empty}</div><div class="lbl">Sem número/modelo</div></div>
    <div class="inventory-kpi"><div class="num">${units}</div><div class="lbl">Unidades encontradas</div></div>
  `;
}
function setupInventoryFilters(){
  refreshInventoryUnitOptions();
  const pendingValue = findInventoryUnitValue(__pendingInventoryUnit);
  if(__pendingInventoryUnit && pendingValue){
    document.getElementById('inventoryUnit').value = pendingValue;
    __pendingInventoryUnit = '';
  }
  ['inventorySearch','inventoryUnit','inventoryStatus','inventorySort'].forEach(id=>{
    document.getElementById(id).addEventListener('input', applyInventoryFilters);
  });
}

function inventorySortRows(rows){
  const sort = document.getElementById('inventorySort')?.value || 'nome';
  const copy = [...rows];
  const text = value => (value ?? '').toString().toLowerCase();
  if(sort === 'unidade') return copy.sort((a,b)=>text(a.unidade).localeCompare(text(b.unidade),'pt-BR') || text(a.nome).localeCompare(text(b.nome),'pt-BR'));
  if(sort === 'status') return copy.sort((a,b)=>inventoryStatus(a).key.localeCompare(inventoryStatus(b).key) || text(a.nome).localeCompare(text(b.nome),'pt-BR'));
  if(sort === 'entrega') return copy.sort((a,b)=>text(b.data_entrega).localeCompare(text(a.data_entrega),'pt-BR') || text(a.nome).localeCompare(text(b.nome),'pt-BR'));
  return copy.sort((a,b)=>text(a.nome).localeCompare(text(b.nome),'pt-BR'));
}

function renderInventoryTable(rows){
  const body = document.getElementById('inventoryBody');
  if(!body) return;
  body.innerHTML = rows.length ? rows.map(row=>{
    const status = inventoryStatus(row);
    const category = inferInventoryCategory(row);
    const categoryLabel = INVENTORY_CATEGORY_LABELS[category] || 'Outros';
    const rowId = row.__id || inventoryBaseId(row);
    const field = (label, value, className='')=>{
      const missing = value == null || String(value).trim() === '';
      return `<div class="inventory-card-field ${className}${missing ? ' missing' : ''}"><span>${label}</span><b>${missing ? 'Não informado' : escHtml(value)}</b></div>`;
    };
    const statusHtml = `<span class="inventory-status ${status.key}">${status.label}</span>`;
    return `<article class="inventory-card ${status.key}">
      <div class="inventory-card-main">
        <div class="inventory-card-main-head">
          <div>
            <div class="inventory-card-kicker">${escHtml(categoryLabel)}</div>
            <h3>${escHtml(row.nome || 'Sem nome')}</h3>
            <span class="inventory-card-unit">${escHtml(row.unidade || 'Unidade não informada')}</span>
          </div>
          <button type="button" class="inventory-edit-btn" data-inventory-edit="${escHtml(rowId)}" aria-label="Editar informações de ${escHtml(row.nome || 'equipamento')}" title="Editar informações"><span class="inventory-edit-icon" aria-hidden="true">✎</span><span class="inventory-edit-label">Editar</span></button>
        </div>
        <div class="inventory-card-meta"><span>${escHtml(row.empresa || 'Empresa não informada')}</span><span>${statusHtml}</span></div>
      </div>
      <div class="inventory-card-grid">
        ${field('Número', row.numero)}
        ${field('E-mail do aparelho', row.email)}
        ${field('Modelo / IMEI', row.modelo, 'inventory-model')}
        ${field('Categoria', categoryLabel)}
        ${field('NF / patrimônio', row.nf_equipamento)}
        ${field('Aquisição', row.data_aquisicao)}
        ${field('Entrega', row.data_entrega)}
        ${field('Valor', row.valor_aquisicao)}
        ${field('Unidade', row.unidade)}
        ${field('Departamento', row.departamento)}
        ${field('Gestor', row.gestor)}
        ${field('Função', row.funcao)}
        ${field('E-mail corporativo', row.email_corporativo)}
        ${field('Observações', row.observacoes, 'inventory-model')}
      </div>
    </article>`;
  }).join('') : '<div class="inventory-muted">Nenhum registro corresponde aos filtros selecionados.</div>';
  document.getElementById('inventoryCount').textContent = `${rows.length} de ${INVENTARIO.length} registros`;
}

function applyInventoryFilters(){
  const q = document.getElementById('inventorySearch').value.trim().toLowerCase();
  const unit = document.getElementById('inventoryUnit').value;
  const statusFilter = document.getElementById('inventoryStatus').value;
  const rows = INVENTARIO.filter(row=>{
    if(selectedInventoryCategory !== 'all' && inferInventoryCategory(row) !== selectedInventoryCategory) return false;
    if(selectedInventoryModel !== 'all' && modelKey(row.modelo) !== selectedInventoryModel) return false;
    if(unit && row.unidade !== unit) return false;
    if(statusFilter && inventoryStatus(row).key !== statusFilter) return false;
    if(q){
      const hay = Object.values(row).join(' ').toLowerCase();
      if(!hay.includes(q)) return false;
    }
    return true;
  });
  renderInventoryTable(inventorySortRows(rows));
}
function exportInventoryCsv(){
  const fields = ['nome','numero','email','modelo','categoria','nf_equipamento','data_aquisicao','data_entrega','valor_aquisicao','empresa','unidade','departamento','gestor','funcao','email_corporativo','observacoes'];
  const esc = value => '"' + (value ?? '').toString().replace(/"/g,'""') + '"';
  const csv = [fields.join(','), ...INVENTARIO.map(row=>fields.map(field=>esc(row[field])).join(','))].join('\\n');
  const blob = new Blob([csv], {type:'text/csv;charset=utf-8;'});
  const url = URL.createObjectURL(blob); const a = document.createElement('a');
  a.href = url; a.download = 'inventario_painel_sem_senhas.csv'; document.body.appendChild(a); a.click();
  document.body.removeChild(a); URL.revokeObjectURL(url);
}

function setupDynamicControls(){
  document.getElementById('btnRefresh')?.addEventListener('click', ()=>{
    const button = document.getElementById('btnRefresh');
    if(button){ button.textContent='Atualizando…'; button.disabled=true; }
    window.location.reload();
  });
  const stamp = document.getElementById('lastRefresh');
  if(stamp) stamp.textContent = 'Leitura local · ' + new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
  setActiveUnit('');
}

// ---------- tabs ----------
function setupTabs(){
  document.querySelectorAll('.tabbtn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      document.querySelectorAll('.tabbtn').forEach(b=>b.classList.remove('active'));
      document.querySelectorAll('.tabpage').forEach(p=>p.classList.remove('active'));
      btn.classList.add('active');
      document.getElementById('tab-'+btn.dataset.tab).classList.add('active');
      if(btn.dataset.tab === 'painel' && window.__map){
        setTimeout(()=>window.__map.invalidateSize(), 50);
      }
    });
  });
  document.getElementById('btnInventoryExport').addEventListener('click', exportInventoryCsv);
  setupInventoryEditor();
}

boot();